// Faithful port of `int(str)` for base 10, returning a BigInt so arbitrarily
// large values behave like Python's unbounded ints.
//
// CPython first runs the text through PyUnicode_TransformDecimalAndSpaceToASCII,
// which folds every White_Space character to a plain space and rewrites every
// Unicode decimal digit as its ASCII counterpart. Only then does the ASCII
// scanner run, and that scanner accepts a narrower whitespace set. This is why
// '١٠', '１０' and '\xa010' all parse while '\x1c10' and '﻿10' do not.

import { PyValueError } from './pyerrors.mjs';
import { strRepr } from './pyrepr.mjs';
import { codePoints } from './pystr.mjs';
import { isAsciiWhitespace, isUnicodeWhitespace, decimalDigitValue } from './pyunicode.mjs';

function transformDecimalAndSpaceToAscii(s) {
  let out = '';

  for (const ch of codePoints(s)) {
    if (isUnicodeWhitespace(ch)) {
      out += ' ';
      continue;
    }
    const value = decimalDigitValue(ch.codePointAt(0));
    out += value >= 0 ? String(value) : ch;
  }

  return out;
}

function stripAsciiWhitespace(s) {
  let start = 0;
  let end = s.length;
  while (start < end && isAsciiWhitespace(s[start])) start++;
  while (end > start && isAsciiWhitespace(s[end - 1])) end--;
  return s.slice(start, end);
}

// A digit run may contain single underscores, but only between digits:
// '1_0' is valid, while '_10', '10_' and '1__0' are not.
const DIGIT_RUN = /^[0-9](?:_?[0-9])*$/;

/**
 * `int(text)`. Returns a BigInt, or throws PyValueError carrying CPython's
 * "invalid literal" message (which quotes the *original* text, not the
 * transformed one).
 */
export function pyInt(text) {
  const transformed = stripAsciiWhitespace(transformDecimalAndSpaceToAscii(text));

  let sign = 1n;
  let body = transformed;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    sign = -1n;
    body = body.slice(1);
  }

  if (!DIGIT_RUN.test(body)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${strRepr(text)}`,
    );
  }

  return sign * BigInt(body.replace(/_/g, ''));
}
=====UNICODE=====
// Unicode character-classification primitives that mirror the exact predicates
// CPython relies on. Two *different* whitespace notions matter here, and the
// reference binary distinguishes them:
//
//   * int(str) folds only characters with the Unicode White_Space property.
//   * str.rstrip() also folds U+001C..U+001F (the ASCII separator controls),
//     which str.isspace() reports as whitespace but White_Space does not.
//
// Keeping them apart is what makes `--a '\x1c10'` fail while `--c '5Q\x1c'`
// succeeds, matching the reference binary.

const RE_WHITE_SPACE = /^\p{White_Space}$/u;
const RE_ND = /^\p{Nd}$/u;

// Everything Python treats as unprintable for repr(): the Other and the
// line/paragraph/space separator categories. Plain U+0020 is the one Zs
// character Python still prints literally.
const RE_NONPRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** Characters with the Unicode White_Space property — the set int() folds. */
export function isUnicodeWhitespace(ch) {
  return RE_WHITE_SPACE.test(ch);
}

/**
 * The set `str.isspace()` reports, i.e. White_Space plus the four ASCII
 * separator controls. This is what `str.strip()`/`rstrip()` remove.
 */
export function isPyStrWhitespace(ch) {
  if (RE_WHITE_SPACE.test(ch)) return true;
  const cp = ch.codePointAt(0);
  return cp >= 0x1c && cp <= 0x1f;
}

/** The ASCII-only whitespace `Py_ISSPACE` accepts during numeric scanning. */
export function isAsciiWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\v' || ch === '\f' || ch === '\r';
}

function isDecimalDigitCodePoint(cp) {
  return cp >= 0 && cp <= 0x10ffff && RE_ND.test(String.fromCodePoint(cp));
}

const digitValueCache = new Map();

/**
 * Numeric value of any Unicode decimal digit (General_Category=Nd), or -1.
 *
 * Nd code points always arrive as complete 0-9 decades, but decades can be
 * directly adjacent (U+1D7CE..U+1D7FF packs five of them back to back). So we
 * walk down to the start of the whole contiguous Nd block and take the offset
 * modulo ten rather than assuming the run is only ten long.
 */
export function decimalDigitValue(cp) {
  const cached = digitValueCache.get(cp);
  if (cached !== undefined) return cached;

  let value = -1;
  if (isDecimalDigitCodePoint(cp)) {
    let blockStart = cp;
    while (blockStart > 0 && isDecimalDigitCodePoint(blockStart - 1)) blockStart--;
    value = (cp - blockStart) % 10;
  }

  digitValueCache.set(cp, value);
  return value;
}

/** Whether repr() may emit this character literally instead of escaping it. */
export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !RE_NONPRINTABLE.test(ch);
}
=====REPR=====
// Reimplementation of CPython's repr() for str and bytes. argparse embeds
// repr(value) in its error text ("invalid int value: '﻿10'"), and print()
// on a bytes object emits its repr, so both spellings have to be exact.

import { codePoints } from './pystr.mjs';
import { isPrintable } from './pyunicode.mjs';

/** `\xXX`, `\uXXXX` or `\UXXXXXXXX` depending on magnitude, as Python picks. */
export function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Python prefers single quotes, switching to double only when the string
// contains a single quote but no double quote.
function chooseQuote(chars) {
  if (chars.includes("'") && !chars.includes('"')) return '"';
  return "'";
}

function escapeCommon(ch, quote) {
  if (ch === '\\') return '\\\\';
  if (ch === quote) return '\\' + quote;
  if (ch === '\n') return '\\n';
  if (ch === '\r') return '\\r';
  if (ch === '\t') return '\\t';
  return null;
}

/** repr() of a str. */
export function strRepr(s) {
  const chars = codePoints(s);
  const quote = chooseQuote(chars);
  let out = quote;

  for (const ch of chars) {
    const common = escapeCommon(ch, quote);
    if (common !== null) {
      out += common;
    } else if (isPrintable(ch)) {
      out += ch;
    } else {
      out += escapeCodePoint(ch.codePointAt(0));
    }
  }

  return out + quote;
}

/**
 * repr() of a bytes object, given its octet values. Unlike str, bytes repr
 * only ever prints the printable ASCII range literally; everything else is
 * escaped as `\xXX`.
 */
export function bytesRepr(octets) {
  const chars = [...octets].map((o) => String.fromCharCode(o));
  const quote = chooseQuote(chars);
  let out = 'b' + quote;

  for (const octet of octets) {
    const ch = String.fromCharCode(octet);
    const common = escapeCommon(ch, quote);
    if (common !== null) {
      out += common;
    } else if (octet >= 0x20 && octet <= 0x7e) {
      out += ch;
    } else {
      out += '\\x' + octet.toString(16).padStart(2, '0');
    }
  }

  return out + quote;
}

// Type converters that argparse names in its error messages. The `name` is the
// spelling argparse uses ("invalid int value: ..."), which for a builtin is
// the function's __name__.

import { pyInt } from '../pyint.mjs';

export const int = { name: 'int', fn: pyInt };
export const str = { name: 'str', fn: (value) => value };
=====STR=====
// Python string helpers. Python strings are sequences of code points, so every
// routine here works on code-point arrays (`[...s]`) rather than UTF-16 units —
// that keeps positions and lengths aligned with what CPython reports.

import { isPyStrWhitespace } from './pyunicode.mjs';

/** Split a string into its code points, the way Python iterates a str. */
export function codePoints(s) {
  return [...s];
}

/** `str.rstrip()` with no argument: drop trailing `str.isspace()` characters. */
export function pyRstrip(s) {
  const chars = codePoints(s);
  let end = chars.length;
  while (end > 0 && isPyStrWhitespace(chars[end - 1])) end--;
  return chars.slice(0, end).join('');
}

/** `str.strip()` with no argument. */
export function pyStrip(s) {
  const chars = codePoints(s);
  let start = 0;
  let end = chars.length;
  while (start < end && isPyStrWhitespace(chars[start])) start++;
  while (end > start && isPyStrWhitespace(chars[end - 1])) end--;
  return chars.slice(start, end).join('');
}

